const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.defineLayout({ name: 'WIDE', width: 13.33, height: 7.5 });
pres.layout = 'WIDE';

// Color palette
const C = {
  primary: '1B3A5C',    // deep navy
  accent: '2E86AB',     // teal blue
  highlight: 'F18F01',  // warm orange
  light: 'F5F7FA',      // off-white bg
  dark: '2D2D2D',       // near-black text
  white: 'FFFFFF',
  gray: '6B7B8D',
};

// Helper: add consistent footer
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 12.3, y: 7.0, w: 0.8, h: 0.3,
    fontSize: 9, color: C.gray, align: 'right', fontFace: '微软雅黑',
  });
  // Bottom accent bar
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 7.2, w: 13.33, h: 0.3, fill: { color: C.primary },
  });
}

// ===== Slide 1: Title =====
const s1 = pres.addSlide();
s1.background = { fill: C.primary };
// Decorative circle
s1.addShape(pres.ShapeType.ellipse, {
  x: 9.5, y: -1.5, w: 5, h: 5, fill: { color: C.accent }, transparency: 70,
});
s1.addShape(pres.ShapeType.ellipse, {
  x: -1.5, y: 4.5, w: 4, h: 4, fill: { color: C.highlight }, transparency: 75,
});
s1.addText('团队协作', {
  x: 1.0, y: 1.8, w: 11, h: 1.5,
  fontSize: 54, bold: true, color: C.white, fontFace: '微软雅黑', align: 'center',
});
s1.addText('打造高效协同的优秀团队', {
  x: 1.0, y: 3.4, w: 11, h: 0.8,
  fontSize: 24, color: C.light, fontFace: '微软雅黑', align: 'center',
});
// Accent line
s1.addShape(pres.ShapeType.rect, {
  x: 5.2, y: 4.4, w: 3, h: 0.06, fill: { color: C.highlight },
});
s1.addText('2024 年度团队建设分享', {
  x: 1.0, y: 5.0, w: 11, h: 0.6,
  fontSize: 16, color: C.gray, fontFace: '微软雅黑', align: 'center',
});

// ===== Slide 2: Why Teamwork Matters =====
const s2 = pres.addSlide();
s2.background = { fill: C.light };
s2.addText('为什么团队协作至关重要？', {
  x: 0.8, y: 0.4, w: 11, h: 0.9,
  fontSize: 32, bold: true, color: C.primary, fontFace: '微软雅黑',
});
s2.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.25, w: 2.5, h: 0.06, fill: { color: C.highlight },
});

const reasons = [
  { icon: '🚀', title: '提升效率', desc: '合理分工让每个人聚焦擅长领域，整体产出远超个人之和' },
  { icon: '💡', title: '激发创新', desc: '多元视角碰撞产生新想法，避免思维盲区与认知局限' },
  { icon: '🛡️', title: '增强韧性', desc: '互相补位与支持使团队在压力下保持稳定交付能力' },
  { icon: '📈', title: '促进成长', desc: '知识共享与反馈文化加速每位成员的技能提升' },
];

reasons.forEach((r, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const bx = 0.8 + col * 6.0;
  const by = 1.7 + row * 2.6;
  // Card background
  s2.addShape(pres.ShapeType.roundRect, {
    x: bx, y: by, w: 5.5, h: 2.2, rectRadius: 0.15,
    fill: { color: C.white }, shadow: { type: 'outer', blur: 6, offset: 2, color: 'CCCCCC', opacity: 0.3 },
  });
  // Icon
  s2.addText(r.icon, {
    x: bx + 0.3, y: by + 0.3, w: 0.8, h: 0.8,
    fontSize: 36, align: 'center', valign: 'middle',
  });
  // Title
  s2.addText(r.title, {
    x: bx + 1.3, y: by + 0.25, w: 3.8, h: 0.5,
    fontSize: 20, bold: true, color: C.primary, fontFace: '微软雅黑',
  });
  // Description
  s2.addText(r.desc, {
    x: bx + 1.3, y: by + 0.85, w: 3.8, h: 1.1,
    fontSize: 14, color: C.dark, fontFace: '微软雅黑', lineSpacingMultiple: 1.3,
  });
});

addFooter(s2, 2);

